'use strict';
function messagesPage(){const m=W().messages;return sHead('sMessages','S05/S65 · J22')+sPolicy('D-014/D-004/D-015')+`<div class="form-panel">${errorBox()}<div class="work-card">${sField('message-text','Fictional message','رسالة خيالية',m.text)}<p class="draft-note">${q('Audience preview: one verified recipient, one ended relationship, one disabled channel. Names/contacts excluded.','معاينة الجمهور: مستلم متحقق منه وعلاقة منتهية وقناة معطلة. الأسماء والاتصالات مستبعدة.')}</p>${property(q('Current intent','النية الحالية'),esc(stateLabel(m.state)))}${sConfirm('message-review')}${sButtons(btn(q('Review audience and message','مراجعة الجمهور والرسالة'),'s-message-review','primary'),btn(q('Queue simulated intent','إضافة نية تجريبية للطابور'),'s-message-queue'),btn(q('Show partial delivery result','إظهار نتيجة تسليم جزئية'),'s-message-result'))}</div>${m.results.length?`<div class="section work-card">${m.results.map(r=>property(q(r.en,r.ar),badge(q(r.state,r.stateAr),r.state==='Provider accepted'?'info':'warn'))).join('')}${sButtons(btn(q('Reconcile unknown attempt only','تسوية المحاولة المجهولة فقط'),'s-message-retry'))}</div>`:''}${notice(q('Delivery boundary','حد التسليم'),q('Queued, provider accepted and read are separate. No message is transmitted; retry cannot recreate the audience intent.','الطابور وقبول المزود والقراءة حالات منفصلة. لا تُرسل رسالة؛ المحاولة لا تعيد إنشاء نية الجمهور.'))}</div>`}
function mediaPage(){const m=W().media;return sHead('sMedia','S33 · J21')+sPolicy('D-014/D-015',q('No actual file picker, upload, personal photo or public token. Private consent and current audience must be verified in implementation.','لا اختيار أو رفع ملفات فعلية أو صور أشخاص أو رموز عامة. يجب التحقق من الموافقة والجمهور الحالي في التنفيذ.'))+`<div class="form-panel">${errorBox()}<div class="work-card"><h2>${q('Private upload review','مراجعة الرفع الخاص')}</h2>${property(q('Audience','الجمهور'),q('Authorized session members only · fictional evidence','أعضاء الحصة المصرح لهم فقط · دليل خيالي'))}${sConfirm('media-review')}${sButtons(btn(q('Reserve two synthetic files','حجز ملفين اصطناعيين'),'s-media-reserve','primary'),btn(q('Advance processing / partial failure','تقديم المعالجة والفشل الجزئي'),'s-media-process'))}</div>${m.items.map(x=>`<div class="work-card section">${property(q('File','الملف'),`<bdi>${x.name}</bdi>`)}${property(t('status'),badge(q(x.state,({reserved:'محجوز',available:'متاح',failed:'فشل'})[x.state]),x.state==='available'?'success':'warn'))}${x.state==='failed'?btn(q('Retry this upload intent','إعادة محاولة هذه النية'),'s-media-retry:'+x.name):x.state==='available'?btn(q('Open authorized preview','فتح معاينة مصرح بها'),'s-media-view:'+x.name):''}</div>`).join('')}${m.state==='viewing'?`<div class="work-card section"><div class="file-preview">${icon('file')}<b>${q('Synthetic private-file placeholder','عنصر نائب لملف خاص اصطناعي')}</b></div>${m.expired?notice(q('Download expired','انتهى التنزيل'),q('Recheck current access before a replacement link.','أعد التحقق من الوصول الحالي قبل رابط بديل.'),'warn'):notice(q('Authorized viewing fixture','نموذج عرض مصرح به'),q('No bearer URL or actual file is generated.','لا يُنشأ رابط حامل أو ملف فعلي.'))}${sButtons(btn(q('Expire access fixture','إنهاء صلاحية المثال'),'s-media-expire'),btn(q('Recheck access and renew fixture','إعادة التحقق وتجديد المثال'),'s-media-renew'))}</div>`:''}</div>`}
function supportPage(){const c=W().support;return sHead('sSupport','S35 · J23')+sPolicy('D-021',q('A support case does not grant tenant private-data access. No impersonation.','حالة الدعم لا تمنح وصولاً إلى بيانات الأكاديمية الخاصة. لا انتحال.'))+`<div class="form-panel">${errorBox()}<div class="work-card">${property(q('Case / scope','الحالة والنطاق'),'SIM-CASE-1 · LAB-OPS · '+q('Synthetic upload issue','مشكلة رفع اصطناعية'))}${property(t('status'),esc(stateLabel(c.state)))}${property(q('Visible mode','نمط العرض'),c.customer?q('Customer projection','عرض العميل'):q('Support operator fixture','نموذج مشغل الدعم'))}${sButtons(btn(c.customer?q('Return to internal view','العودة للعرض الداخلي'):q('Inspect customer view','فحص عرض العميل'),'s-support-mode'))}</div><div class="section work-card"><h3>${q('Customer conversation','محادثة العميل')}</h3>${c.replies.map(r=>`<p class="notice">${esc(r)}</p>`).join('')||`<p class="subtitle">${q('No reply yet','لا يوجد رد بعد')}</p>`}${!c.customer?`${sField('support-reply','Customer-visible reply','رد ظاهر للعميل')}${sConfirm('support-reply-review')}${sButtons(btn(q('Record simulated reply','تسجيل رد تجريبي'),'s-support-reply','primary'))}`:''}</div>${!c.customer?`<div class="section work-card"><h3>${q('Private internal notes','ملاحظات داخلية خاصة')}</h3>${c.notes.map(n=>`<p class="notice warn">${esc(n)}</p>`).join('')}${sField('support-note','Internal note','ملاحظة داخلية')}${sButtons(btn(q('Save internal note','حفظ ملاحظة داخلية'),'s-support-note'),btn(q('Escalate case','تصعيد الحالة'),'s-support-escalate'),btn(q('Resolve with evidence','حل مع دليل'),'s-support-resolve'))}<p class="draft-note">${q('Attachment staging/partial failure uses the private media pattern; no files attached in this lab.','تهيئة المرفقات والفشل الجزئي تتبع نمط الوسائط الخاصة؛ لا مرفقات فعلية هنا.')}</p></div>`:''}</div>`}
function inventoryPage(){const s=W().stock;return sHead('sInventory','S34 · J24')+sPolicy('D-017',q('Basic quantity movement fixture; no valuation, purchasing or negative-stock business rule is selected. The fixture rejects overspending stock.','نموذج حركة كمية أساسي؛ لا تقييم أو شراء أو سياسة مخزون سالب معتمدة. المثال يرفض تجاوز الكمية.'))+`<div class="form-panel">${errorBox()}<div class="work-card">${property(q('Item','الصنف'),q('Demo training cones · pieces','أقماع تدريب تجريبية · قطعة'))}${property(q('West / East branch','الفرع الغربي / الشرقي'),`${s.west} / ${s.east}`)}${sField('stock-qty','Quantity · positive integer','كمية صحيحة موجبة','','number')}${sField('stock-reason','Movement reason / reference','سبب الحركة ومرجعها')}${sConfirm('stock-review')}${sButtons(btn(q('Receive into West','استلام في الغرب'),'s-stock-receive','primary'),btn(q('Transfer West → East','نقل من الغرب إلى الشرق'),'s-stock-transfer'),btn(q('Count adjustment · add to West','تسوية عدّ · إضافة للغرب'),'s-stock-adjust'))}</div><div class="section work-card"><h3>${q('Movement history','سجل الحركات')}</h3>${s.movements.map(x=>`<div class="task-row"><bdi>${x.ref}</bdi> · ${esc(x.kind)} · ${x.qty}<span class="muted">${esc(x.reason)}</span></div>`).join('')||`<p class="subtitle">${q('Measured fixture stock is zero; a failed read uses an unavailable state instead.','المخزون المقاس في المثال صفر؛ فشل القراءة يعرض عدم الإتاحة بدلاً من ذلك.')}</p>`}</div></div>`}
function exportPage(){const j=W().export;return sHead('sExport','S48 · J25')+sPolicy('Domain definitions / D-015')+`<div class="form-panel">${errorBox()}<div class="work-card">${property(q('Definition','التعريف'),q('Authorized synthetic player directory, all60 frozen row IDs;25 visible per page','دليل لاعبين اصطناعي مصرح به، جميع المعرّفات الستين ثابتة؛ ٢٥ ظاهرة بالصفحة'))}${property(q('Scope / snapshot','النطاق واللقطة'),'LAB-OPS · synthetic-row-manifest-v1 · 2026-11-02T12:00:00Z')}${property(q('Columns','الأعمدة'),q('Synthetic record ID and display label only; no private notes','معرّف السجل الاصطناعي وتسمية العرض فقط؛ دون ملاحظات خاصة'))}${property(t('status'),esc(stateLabel(j.state)))}${property(q('Progress / complete scope','التقدم والنطاق الكامل'),`${j.done} / ${j.rows}`)}${sConfirm('export-review')}${sButtons(btn(q('Freeze scope and queue export','تثبيت النطاق وإضافة التصدير'),'s-export-start','primary'),btn(q('Advance one page','تقديم صفحة واحدة'),'s-export-step'),btn(q('Simulate failed job','محاكاة فشل المهمة'),'s-export-fail'),btn(q('Retry original frozen intent','إعادة النية الأصلية الثابتة'),'s-export-retry'))}${j.state==='ready'?sButtons(btn(q('Download synthetic complete CSV','تنزيل CSV اصطناعي كامل'),'s-export-download'),btn(q('Expire artifact','إنهاء صلاحية الملف'),'s-export-expire')):''}${j.state==='expired'?notice(q('Artifact expired','انتهت صلاحية الملف'),q('Reauthorize and freeze a new request. Old artifact is not revived.','أعد التصريح وتثبيت طلب جديد. لا يُحيى الملف القديم.'),'warn'):''}</div></div>`}
function privacyPage(){const p=W().privacy;return sHead('sPrivacy','S49 · J26')+sPolicy('D-004/D-015/D-001/D-019',q('No legal deadline, retention period or deletion authority is selected. Only a fictional request is tracked; nothing is erased.','لم تُختَر مهلة قانونية أو مدة احتفاظ أو سلطة حذف. يُتتبَّع طلب خيالي فقط؛ لا يُمحى شيء.'))+`<div class="form-panel">${errorBox()}<div class="work-card">${property(q('Request scope','نطاق الطلب'),'LAB-OPS · synthetic person DEMO-PRIV-1')}${property(t('status'),esc(stateLabel(p.state)))}${property(q('Hold review','مراجعة الحجز'),p.hold?q('Hold applies · deletion cannot proceed','يوجد حجز · لا يمكن متابعة الحذف'):q('No hold asserted in fixture; legal review still pending','لا حجز مفترض في المثال؛ المراجعة القانونية معلّقة'))}${sField('privacy-reason','Authority evidence / handling reason','دليل السلطة وسبب المعالجة')}${sConfirm('privacy-review')}${sButtons(btn(q('Create scoped request','إنشاء طلب محدد النطاق'),'s-privacy-start','primary'),btn(q('Review authority and holds','مراجعة السلطة والحجز'),'s-privacy-review'),btn(q('Toggle hold fixture','تبديل مثال الحجز'),'s-privacy-hold'),btn(q('Prepare subsystem checklist','إعداد قائمة الأنظمة'),'s-privacy-prepare'))}</div><div class="section work-card"><h3>${q('Outcome evidence per subsystem','دليل النتيجة لكل نظام')}</h3>${property(q('Database / private objects','القاعدة والكائنات الخاصة'),q('Design checklist only · no erasure','قائمة تصميم فقط · لا محو'))}${property(q('Identity / external providers','الهوية والمزودون الخارجيون'),p.cleanup?q('Fictional cleanup reviewed','رُوجع التنظيف الخيالي'):q('External cleanup pending','التنظيف الخارجي معلّق'))}${property(q('Backups','النسخ الاحتياطية'),q('Retention policy unresolved; restore must reconcile deletion/hold ledger','سياسة الاحتفاظ غير محسومة؛ يجب تسوية سجل الحذف والحجز عند الاستعادة'))}${sButtons(btn(q('Record external cleanup evidence fixture','تسجيل مثال دليل تنظيف خارجي'),'s-privacy-evidence'),btn(q('Close simulated case after checklist','إغلاق الحالة التجريبية بعد القائمة'),'s-privacy-close'))}</div></div>`}
function operationsAction(k,v){const w=W(),m=w.messages,media=w.media,c=w.support,s=w.stock,j=w.export,p=w.privacy;if(k.startsWith('s-message-')){if(k==='s-message-review'){if(!sValue('message-text')||!sCheck('message-review')){sError();return true}m.text=sValue('message-text');m.state='reviewed'}else if(k==='s-message-queue'){if(m.state!=='reviewed'){sError();return true}m.state='queued'}else if(k==='s-message-result'){if(m.state!=='queued'){sError();return true}m.state='partial';m.results=[{en:'Current authorized recipient',ar:'مستلم مصرح به حالياً',state:'Provider accepted',stateAr:'قبله المزود'},{en:'Ended relationship',ar:'علاقة منتهية',state:'Suppressed',stateAr:'مستبعد'},{en:'Disabled push channel',ar:'قناة دفع معطلة',state:'Disabled',stateAr:'معطلة'},{en:'Email attempt',ar:'محاولة البريد',state:'Outcome unknown',stateAr:'نتيجة مجهولة'}]}else if(k==='s-message-retry'){m.results=m.results.map(r=>r.state==='Outcome unknown'?{...r,state:'Failed after reconciliation',stateAr:'فشل بعد التسوية'}:r);m.state='partial · unresolved failed attempt'}sSaved(sh('sMessages'));return true}
if(k.startsWith('s-media-')){if(k==='s-media-reserve'){if(!sCheck('media-review')||media.items.length){sError();return true}media.items=[{name:'synthetic-a.svg',state:'reserved'},{name:'synthetic-b.svg',state:'reserved'}];media.state='reserved'}else if(k==='s-media-process'){if(media.state!=='reserved'){sError();return true}media.items[0].state='available';media.items[1].state='failed';media.state='partial'}else if(k==='s-media-retry'){const file=media.items.find(x=>x.name===v);if(file?.state!=='failed'){sError();return true}file.state='available'}else if(k==='s-media-view'){if(!media.items.some(x=>x.name===v&&x.state==='available')){sError();return true}media.state='viewing'}else if(k==='s-media-expire')media.expired=true;else if(k==='s-media-renew')media.expired=false;sSaved(sh('sMedia'));return true}
if(k==='s-support-mode'){c.customer=!c.customer;render();return true}if(k.startsWith('s-support-')){if(c.customer){sError(t('restricted'));return true}if(k==='s-support-reply'){if(!sValue('support-reply')||!sCheck('support-reply-review')){sError();return true}c.replies.push(sValue('support-reply'));c.state='waiting for customer · delivery pending'}else if(k==='s-support-note'){if(!sValue('support-note')){sError();return true}c.notes.push(sValue('support-note'))}else if(k==='s-support-escalate')c.state='escalated';else if(k==='s-support-resolve'){if(!sValue('support-note')){sError();return true}c.state='resolved · evidence fixture'}sSaved(sh('sSupport'));return true}
if(k.startsWith('s-stock-')){const qty=+sValue('stock-qty'),reason=sValue('stock-reason');if(!Number.isSafeInteger(qty)||qty<=0||!reason||!sCheck('stock-review')){sError();return true}if(k==='s-stock-transfer'&&qty>s.west){sError(q('Insufficient current stock; neither location changed.','المخزون الحالي غير كافٍ؛ لم يتغير أي موقع.'));return true}if(k==='s-stock-transfer'){s.west-=qty;s.east+=qty}else s.west+=qty;s.movements.push({ref:'SIM-MOVE-'+(s.movements.length+1),kind:k,qty,reason});sSaved(sh('sInventory'));return true}
if(k.startsWith('s-export-')){if(k==='s-export-start'){if(!sCheck('export-review')||['queued','processing','ready'].includes(j.state)){sError();return true}j.state='queued';j.done=0}else if(k==='s-export-step'){if(!['queued','processing'].includes(j.state)){sError();return true}j.done=Math.min(j.rows,j.done+25);j.state=j.done===j.rows?'ready':'processing'}else if(k==='s-export-fail')j.state='failed';else if(k==='s-export-retry'){if(j.state!=='failed'){sError();return true}j.state='processing'}else if(k==='s-export-expire')j.state='expired';else if(k==='s-export-download'){if(j.state!=='ready'||j.done!==60){sError();return true}const text='synthetic_id,label\n'+Array.from({length:60},(_,i)=>`DEMO-${i+1},Fictional player ${i+1}`).join('\n');const blob=new Blob([text],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='academyos-synthetic-complete-scope.csv';a.click();URL.revokeObjectURL(url)}sSaved(sh('sExport'));return true}
if(k.startsWith('s-privacy-')){if(k==='s-privacy-hold')p.hold=!p.hold;else if(k==='s-privacy-start'){if(!sValue('privacy-reason')||!sCheck('privacy-review')||p.state!=='idle'){sError();return true}p.state='request recorded'}else if(k==='s-privacy-review'){if(p.state!=='request recorded'||!sValue('privacy-reason')){sError();return true}p.state=p.hold?'held':'authority reviewed fixture'}else if(k==='s-privacy-prepare'){if(p.hold||p.state!=='authority reviewed fixture'){sError(q('Hold or incomplete authority review blocks preparation.','يمنع الحجز أو نقص مراجعة السلطة الإعداد.'));return true}p.state='subsystem checklist prepared'}else if(k==='s-privacy-evidence'){if(p.state!=='subsystem checklist prepared'){sError();return true}p.cleanup=true}else if(k==='s-privacy-close'){if(!p.cleanup||p.hold||p.state!=='subsystem checklist prepared'){sError();return true}p.state='simulated case closed · no actual erasure'}sSaved(sh('sPrivacy'));return true}return false}
